#!/bin/sh
# Build the Miyoo SDL2 fork (sdl2/) for ARM and install it to a prefix.
#
# Run INSIDE the build container, from the repo root:
#
#   docker run --rm -v "$PWD":/root/workspace/Miyoo_port miyoo-build \
#     bash /root/workspace/Miyoo_port/scripts/port/build_miyoo_sdl2.sh
#
# Output: $PREFIX (default /root/miyoo-sdl2-prefix) with include/SDL2 and lib/.
#
# Why build from source instead of using sdl2/prebuilt/*.so: SDL_config.h is
# GENERATED by configure, and SDL_sysvideo.h/SDL_audio.h struct layouts depend
# on which drivers are enabled. The prebuilt .so files cannot be paired with an
# unconfigured header tree, and the tree in sdl2/sdl2/include/ has no __linux__
# branch at all (it falls through to SDL_config_minimal.h on ARM).
set -eu

REPO=${REPO:-/root/workspace/Miyoo_port}
# Inside the mounted repo, so the prefix survives between `docker run --rm`
# invocations (anything under /root is discarded with the container).
PREFIX=${PREFIX:-$REPO/build_miyoo_deps}
GL_VARIANT=${GL_VARIANT:-640x480}
WORK=${WORK:-/root/miyoo-dep}

export CROSS=${CROSS:-/opt/miyoomini-toolchain/usr/bin/arm-linux-gnueabihf-}
export CC=${CROSS}gcc
export CXX=${CROSS}g++
export AR=${CROSS}ar
export AS=${CROSS}as
export LD=${CROSS}ld
export RANLIB=${CROSS}ranlib
export STRIP=${CROSS}strip
export HOST=arm-linux

mkdir -p "$WORK" "$PREFIX"

echo ">> compiler: $($CC --version | head -1)"

# ---- 1. json-c -----------------------------------------------------------------
# The mini AUDIO driver really uses it: SDL_audio_mini.c reads the system volume
# out of a json-c config file, so this one is a link dependency, not just a
# header.
if [ ! -f "$PREFIX/lib/libjson-c.so" ]; then
    echo ">> json-c"
    rm -rf "$WORK/json-c-0.15"
    tar -xzf "$REPO/sdl2/sdl2/dependency/json-c-0.15.tar.gz" -C "$WORK"
    # The bundled tarball is a git snapshot with no generated ./configure, so
    # build it with CMake through the repo's own Miyoo toolchain file - which
    # doubles as a check that that file works.
    cmake -S "$WORK/json-c-0.15" -B "$WORK/json-c-build" \
        -DCMAKE_TOOLCHAIN_FILE="$REPO/cmake/miyoomini-armhf.cmake" \
        -DCMAKE_INSTALL_PREFIX="$PREFIX" \
        -DBUILD_SHARED_LIBS=ON \
        -DBUILD_STATIC_LIBS=OFF \
        -DBUILD_TESTING=OFF \
        > "$WORK/json-c.log" 2>&1 &&
    cmake --build "$WORK/json-c-build" --parallel "$(nproc)" >> "$WORK/json-c.log" 2>&1 &&
    # `cmake --install` needs CMake 3.15; the toolchain base image ships 3.13.
    cmake --build "$WORK/json-c-build" --target install >> "$WORK/json-c.log" 2>&1 \
        || { echo "json-c build failed; tail:"; tail -30 "$WORK/json-c.log"; exit 1; }
fi

# ---- 2. SDL_image header -------------------------------------------------------
# SDL_video_mini.c does `#include "SDL_image.h"` but never calls an IMG_*
# function, so only the header is needed. Building the library would drag in
# libpng/libjpeg/webp for a symbol nothing references.
IMG_INC="$WORK/SDL2_image-2.8.1/include"
if [ ! -f "$IMG_INC/SDL_image.h" ]; then
    echo ">> SDL2_image (header only)"
    rm -rf "$WORK/SDL2_image-2.8.1"
    tar -xzf "$REPO/sdl2/sdl2/dependency/SDL2_image-2.8.1.tar.gz" -C "$WORK"
fi

# ---- 3. SDL2 -------------------------------------------------------------------
cd "$REPO/sdl2"

# configure.ac's video-mini branch links -L. -lEGL -lGLESv2, i.e. it expects
# those two beside the SDL sources.
ln -sf ../prebuilt/$GL_VARIANT/libEGL.so    sdl2/libEGL.so
ln -sf ../prebuilt/$GL_VARIANT/libGLESv2.so sdl2/libGLESv2.so

cd sdl2

if [ ! -f ./configure ]; then
    echo ">> autogen"
    ./autogen.sh
fi

echo ">> configure SDL2"
# SDL's Makefile takes CFLAGS (= @BUILD_CFLAGS@) and EXTRA_CFLAGS; it has no
# CPPFLAGS variable, so the dependency include paths have to ride on CFLAGS or
# they never reach the mini drivers' compile lines.
CFLAGS="-I$PREFIX/include -I$PREFIX/include/SDL2 -I$IMG_INC" \
LDFLAGS="-L$PREFIX/lib" \
./configure \
    --prefix="$PREFIX" \
    --host="$HOST" \
    --disable-oss \
    --disable-alsa \
    --enable-audio-mini \
    --enable-video-mini \
    --disable-video-opengl \
    --disable-video-opengles \
    --disable-video-opengles2 \
    --disable-video-x11 \
    --disable-video-kmsdrm \
    --disable-video-vulkan \
    --disable-video-wayland \
    --disable-video-dummy \
    --disable-joystick-virtual \
    --disable-jack \
    --disable-power \
    --disable-ime \
    --disable-dbus \
    --disable-fcitx \
    --disable-hidapi \
    --disable-libudev \
    --disable-sndio \
    --disable-diskaudio \
    --disable-pulseaudio \
    --disable-dummyaudio \
    --disable-pipewire \
    > "$WORK/sdl2-configure.log" 2>&1 || { tail -40 "$WORK/sdl2-configure.log"; exit 1; }

echo ">> make SDL2"
make -j"$(nproc)" > "$WORK/sdl2-make.log" 2>&1 || { tail -40 "$WORK/sdl2-make.log"; exit 1; }
make install >> "$WORK/sdl2-make.log" 2>&1 || { tail -40 "$WORK/sdl2-make.log"; exit 1; }
# The GLES/EGL pair ships beside the binary on the device, so put them in the
# prefix's lib/ where package_miyoo.sh picks them up.
cp "../prebuilt/$GL_VARIANT/libEGL.so"    "$PREFIX/lib/"
cp "../prebuilt/$GL_VARIANT/libGLESv2.so" "$PREFIX/lib/"

echo ">> built:"
ls -l "$PREFIX/lib/libSDL2-2.0.so.0" "$PREFIX/lib/libjson-c.so" "$PREFIX/include/SDL2/SDL.h"
echo ">> SDL2 for Miyoo installed to $PREFIX"
